rows=[int(x) for x in open('/challenge/qr_code.txt').read().split()]
from PIL import Image
for inv in (0,1):
    n=29;s=10;img=Image.new('1',((n+8)*s,(n+8)*s),1)
    for r,v in enumerate(rows):
        for c in range(n):
            bit=(v>>(n-1-c))&1
            if bit^inv==1:
                for i in range(s):
                    for j in range(s): img.putpixel(((c+4)*s+j,(r+4)*s+i),0)
    img.save(f'/work/q{inv}.png')
try:
    from pyzbar.pyzbar import decode
    for inv in (0,1):print(decode(Image.open(f'/work/q{inv}.png')))
except Exception as e:print(e)
for v in rows[:3]:print(format(v,'029b'))

